    queue<int> q;

    for (int e = 0; e < E; ++e) {
        for (int v = 0; v < V; ++v) {
            if (coeff[e][v] > 0) ++degree[e];
        }
        if (degree[e] == 1) q.push(e);
    }

    vector<bool> known(V, false);
    vector<cpp_int> value(V);

    while (!q.empty()) {
        int e = q.front();
        q.pop();

        if (degree[e] != 1) continue;

        int v = -1;
        for (int x = 0; x < V; ++x) {
            if (coeff[e][x] > 0 && !known[x]) {
                v = x;
                break;
            }
        }
        if (v == -1) continue;

        int count = coeff[e][v];
        value[v] = residual[e] / count;
        known[v] = true;

        for (int f = 0; f < E; ++f) {
            int occurrences = coeff[f][v];
            if (occurrences == 0) continue;

            residual[f] -= cpp_int(occurrences) * value[v];
            coeff[f][v] = 0;
            --degree[f];

            if (degree[f] == 1) q.push(f);
        }
    }

    for (int v = 0; v < V; ++v) {
        if (present[v]) {
            cout << char('a' + v / 26) << char('a' + v % 26)
                 << ' ' << value[v] << '\n';
        }
    }

    return 0;
}
